import{_ as a,c as n,o as e,ag as t}from"./chunks/framework.CQuhCYrb.js";const y=JSON.parse('{"title":"Religion-in-COG-Analysis","description":"","frontmatter":{"title":"Religion-in-COG-Analysis"},"headers":[],"relativePath":"general/religion-in-cog-analysis.md","filePath":"general/religion-in-cog-analysis.md","lastUpdated":null}'),o={name:"general/religion-in-cog-analysis.md"};function s(r,i,l,c,h,d){return e(),n("div",null,[...i[0]||(i[0]=[t('<h1 id="religion-in-cog-analysis" tabindex="-1">Religion-in-COG-Analysis <a class="header-anchor" href="#religion-in-cog-analysis" aria-label="Permalink to &quot;Religion-in-COG-Analysis&quot;">​</a></h1><h2 id="religion-in-cog-analysis-1" tabindex="-1">Religion-in-COG-Analysis <a class="header-anchor" href="#religion-in-cog-analysis-1" aria-label="Permalink to &quot;Religion-in-COG-Analysis&quot;">​</a></h2><h3 id="relationships-with-god-and-community-as-critical-nodes-in-center-of-gravity-analysis" tabindex="-1">Relationships with God and Community as Critical Nodes in Center of Gravity Analysis <a class="header-anchor" href="#relationships-with-god-and-community-as-critical-nodes-in-center-of-gravity-analysis" aria-label="Permalink to &quot;Relationships with God and Community as Critical Nodes in Center of Gravity Analysis&quot;">​</a></h3><p><a href="https://thestrategybridge.org/the-bridge/2018/3/21/relationships-with-god-and-community-as-critical-nodes-in-center-of-gravity-analysis" target="_blank" rel="noreferrer">https://thestrategybridge.org/the-bridge/2018/3/21/relationships-with-god-and-community-as-critical-nodes-in-center-of-gravity-analysis</a></p><p>U.S. joint doctrine fails to account for critical relationships with a person’s conception of god and their community, which impacts the operational environment. Social network analysis further hampers strategists’ ability to account for these significant relationships by only accounting for concrete nodes and links. The political, military, economic, social, information, and infrastructure framework is a WEIRD approach that ignores the critical role that some form of religion plays in every society.</p><p>The article suggests that planners and strategists should develop a formal accounting for subjective perspectives of religion and significant relationships with the community and god that is separate from the current black box of social and cultural analysis.</p>',6)])])}const p=a(o,[["render",s]]);export{y as __pageData,p as default};
